import{_ as a,o as t,c as l,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Atajos de teclado y gestos","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/hotkeys.md","filePath":"es-ES/user-guide/hotkeys.md","lastUpdated":1788171291000}'),n={name:"es-ES/user-guide/hotkeys.md"};function r(s,e,i,d,c,g){return t(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="atajos-de-teclado-y-gestos" tabindex="-1">Atajos de teclado y gestos <a class="header-anchor" href="#atajos-de-teclado-y-gestos" aria-label="Permalink to &quot;Atajos de teclado y gestos&quot;">​</a></h1><p>Lertaro adopta una filosofía de interacción centrada en el teclado, complementada con prácticos gestos de ratón y navegación rápida en cascada. Excepto las teclas fijas, todos los atajos globales y de la aplicación se pueden personalizar en <a href="./settings/hotkeys-page.html"><strong>Configuración → Atajos de teclado</strong></a>.</p><h2 id="_1-tabla-resumen-de-atajos-globales" tabindex="-1">1. Tabla resumen de atajos globales <a class="header-anchor" href="#_1-tabla-resumen-de-atajos-globales" aria-label="Permalink to &quot;1. Tabla resumen de atajos globales&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Acción</th><th style="text-align:left;">Atajo predeterminado</th><th style="text-align:left;">Descripción y detalles de interacción</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Mostrar/Ocultar Ventana rápida</strong></td><td style="text-align:left;">Doble pulsación de <code>Ctrl</code></td><td style="text-align:left;">Configurable en modo doble pulsación o combinación estándar (p. ej. <code>Alt+Space</code>, <code>Win+Space</code>). Si se activa <strong>Abrir el panel principal de forma predeterminada</strong>, este atajo abre la Ventana principal: al mostrarla por primera vez solo la lleva al primer plano y le da el foco una vez; si está visible pero inactiva la vuelve a activar, y si ya está activa la cierra al pulsar de nuevo. No se mantiene automáticamente siempre encima.</td></tr><tr><td style="text-align:left;"><strong>Salto rápido (Quick Jump)</strong></td><td style="text-align:left;"><code>Ctrl+G</code></td><td style="text-align:left;">En cuadros de diálogo, salta directamente a la carpeta consultada recientemente en exploradores o en el Panel rápido.</td></tr><tr><td style="text-align:left;"><strong>Seleccionar elemento siguiente</strong></td><td style="text-align:left;"><code>Ctrl+N</code> o <code>↓</code></td><td style="text-align:left;">Mueve el resaltado hacia abajo. En el Panel rápido se desplaza fluidamente entre grupos. Con el Panel de inicio rápido visible y la consulta vacía, <code>Ctrl+N</code> recorre la siguiente fuente y vuelve a la primera al llegar al final.</td></tr><tr><td style="text-align:left;"><strong>Seleccionar elemento anterior</strong></td><td style="text-align:left;"><code>Ctrl+P</code> o <code>↑</code></td><td style="text-align:left;">Mueve el resaltado hacia arriba. En el Panel rápido también se desplaza entre grupos. Con el Panel de inicio rápido visible y la consulta vacía, <code>Ctrl+P</code> recorre la fuente anterior y vuelve a la última al llegar al principio.</td></tr><tr><td style="text-align:left;"><strong>Saltar a resultados 1–9</strong></td><td style="text-align:left;"><code>Ctrl</code> + <code>1</code>–<code>9</code></td><td style="text-align:left;">Modificador personalizable. Aparecen distintivos numéricos junto a los resultados para apertura instantánea.</td></tr><tr><td style="text-align:left;"><strong>Abrir Menú de acciones</strong></td><td style="text-align:left;"><code>Ctrl+O</code> o <code>→</code></td><td style="text-align:left;">Despliega el menú contextual de acciones (copiar ruta, propiedades, ejecutar como admin, operaciones de archivo, etc.).</td></tr><tr><td style="text-align:left;"><strong>Autocompletar desde selección</strong></td><td style="text-align:left;"><code>Ctrl+Tab</code></td><td style="text-align:left;">Rellena la barra de búsqueda con el nombre o ruta completa del elemento seleccionado para refinamiento.</td></tr><tr><td style="text-align:left;"><strong>Vista previa instantánea QuickLook</strong></td><td style="text-align:left;"><code>Alt+P</code></td><td style="text-align:left;">Abre/cierra el panel lateral de vista previa (imágenes, documentos, reproducción de audio/vídeo, árboles de carpetas).</td></tr><tr><td style="text-align:left;"><strong>Término de búsqueda anterior</strong></td><td style="text-align:left;"><code>Alt+Up</code></td><td style="text-align:left;">Retrocede por el historial reciente de búsquedas.</td></tr><tr><td style="text-align:left;"><strong>Término de búsqueda siguiente</strong></td><td style="text-align:left;"><code>Alt+Down</code></td><td style="text-align:left;">Avanza por el historial reciente de búsquedas.</td></tr><tr><td style="text-align:left;"><strong>Eliminar término de historial</strong></td><td style="text-align:left;"><code>Ctrl+Delete</code></td><td style="text-align:left;">Elimina la palabra clave mostrada actualmente del historial de búsqueda.</td></tr><tr><td style="text-align:left;"><strong>Abrir Ventana principal</strong></td><td style="text-align:left;"><code>Ctrl+F</code></td><td style="text-align:left;">Abre la ventana principal de gran tamaño manteniendo la búsqueda actual.</td></tr><tr><td style="text-align:left;"><strong>Abrir ventana LocalSend</strong></td><td style="text-align:left;"><code>Ctrl+S</code></td><td style="text-align:left;">Abre la ventana de transferencia inalámbrica LocalSend para enviar archivos o texto a otros dispositivos.</td></tr><tr><td style="text-align:left;"><strong>Fijar ventana (Mantener visible)</strong></td><td style="text-align:left;"><code>Ctrl+T</code></td><td style="text-align:left;">Bloquea la ventana abierta al perder el foco (ideal para pegar búsquedas de varias fuentes).</td></tr><tr><td style="text-align:left;"><strong>Mostrar/Ocultar Panel rápido</strong></td><td style="text-align:left;"><code>Ctrl+F2</code></td><td style="text-align:left;">Acopla el panel rápido junto a la ventana activa con archivos recientes, favoritos y espacios de trabajo.</td></tr></tbody></table><h2 id="_2-icono-de-busqueda-y-gestos-de-raton" tabindex="-1">2. Icono de búsqueda y gestos de ratón <a class="header-anchor" href="#_2-icono-de-busqueda-y-gestos-de-raton" aria-label="Permalink to &quot;2. Icono de búsqueda y gestos de ratón&quot;">​</a></h2><p>El pequeño logotipo en la barra de búsqueda no es solo estético: ofrece múltiples gestos rápidos:</p><h3 id="gestos-del-icono-en-la-ventana-rapida" tabindex="-1">Gestos del icono en la Ventana rápida <a class="header-anchor" href="#gestos-del-icono-en-la-ventana-rapida" aria-label="Permalink to &quot;Gestos del icono en la Ventana rápida&quot;">​</a></h3><ul><li><strong>Clic izquierdo</strong>: Despliega el menú contextual principal (Mostrar ventana principal, Cambiar atajo, Configuración, Acerca de, Salida limpia, Salir). &quot;Mostrar ventana principal&quot; transfiere tu búsqueda activa.</li><li><strong>Clic izquierdo y arrastrar</strong>: Arrastra la barra de búsqueda para reubicarla. <strong>Mantener <code>Ctrl</code> mientras arrastras</strong> bloquea el movimiento al <strong>eje vertical</strong>, manteniendo la alineación horizontal intacta.</li><li><strong>Clic derecho</strong>: Restablece instantáneamente la Ventana rápida a su posición central predeterminada en pantalla sin alterar dimensiones.</li><li><strong>Clic central</strong>: Alterna el estado &quot;Fijar ventana&quot;. El logotipo se ilumina mientras está fijada.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Las coordenadas recordadas para la Ventana rápida son <strong>coordenadas relativas proporcionales</strong> a ese monitor. Al invocarla en otra pantalla con distinta resolución o escala DPI, Lertaro recalcula la posición automáticamente dentro de los límites visibles.</p></div><h3 id="iconos-en-la-ventana-incrustada-y-ventana-principal" tabindex="-1">Iconos en la Ventana incrustada y Ventana principal <a class="header-anchor" href="#iconos-en-la-ventana-incrustada-y-ventana-principal" aria-label="Permalink to &quot;Iconos en la Ventana incrustada y Ventana principal&quot;">​</a></h3><ul><li><strong>Ventana incrustada</strong>: Al incrustarse en diálogos nativos (Abrir/Guardar/Examinar), hacer clic izquierdo en el icono abre el menú de <a href="#3-navegacion-rapida-activadores-de-raton"><strong>Navegación rápida</strong></a>; desactivado en el Explorador ordinario.</li><li><strong>Ventana principal</strong>: Al hacer clic izquierdo en el icono se abre el menú contextual; <strong>Mostrar ventana principal</strong> se oculta porque la ventana ya está abierta. El clic central alterna el estado de fijación de la ventana.</li></ul><h2 id="_3-navegacion-rapida-activadores-de-raton" tabindex="-1">3. Navegación rápida (Activadores de ratón) <a class="header-anchor" href="#_3-navegacion-rapida-activadores-de-raton" aria-label="Permalink to &quot;3. Navegación rápida (Activadores de ratón)&quot;">​</a></h2><p>La Navegación rápida te permite acceder a directorios frecuentes y archivos recientes únicamente con clics de ratón, sin teclear.</p><h3 id="entornos-compatibles" tabindex="-1">Entornos compatibles <a class="header-anchor" href="#entornos-compatibles" aria-label="Permalink to &quot;Entornos compatibles&quot;">​</a></h3><ul><li><strong>Espacio vacío del Escritorio</strong>: Clic central (o doble clic izquierdo opcional) para abrir el menú. Al hacer clic en una carpeta o archivo se abre directamente.</li><li><strong>Explorador de archivos</strong>: Clic central en zonas vacías del Explorador; al hacer clic en un elemento, la ventana navega directamente a esa carpeta.</li><li><strong>Exploradores de terceros</strong>: Clic central en la lista de archivos de Directory Opus, Total Commander, XYplorer, Files y One Commander (ver <a href="./file-manager-support.html"><strong>Exploradores de archivos compatibles</strong></a>).</li><li><strong>Diálogos de archivo</strong>: Clic central o clic en el icono incrustado dentro de diálogos Abrir/Guardar para saltar a la carpeta de destino sin confirmar accidentalmente.</li></ul><h3 id="estructura-del-menu-en-cascada" tabindex="-1">Estructura del menú en cascada <a class="header-anchor" href="#estructura-del-menu-en-cascada" aria-label="Permalink to &quot;Estructura del menú en cascada&quot;">​</a></h3><p>Impulsado por el plugin <strong>Folder Cascader</strong>:</p><ol><li><strong>Carpetas abiertas actualmente</strong>: Agrupa y desduplica carpetas activas de todos los exploradores abiertos.</li><li><strong>Favoritos e Historial</strong>: Muestra elementos marcados con estrella e historial de visitas recientes.</li><li><strong>Categorías personalizadas</strong>: Configura submenús anidados en <strong>Configuración → Plugins → Folder Cascader</strong> (p. ej. <code>Trabajo/ProyectoA</code>).</li><li><strong>Añadir carpeta rápida (Botón <code>+</code>)</strong>: Cada encabezado de submenú cuenta con un botón <code>+</code> para guardar el directorio activo directamente en esa categoría.</li></ol><h2 id="_4-teclas-fijas-basicas-no-configurables" tabindex="-1">4. Teclas fijas básicas (No configurables) <a class="header-anchor" href="#_4-teclas-fijas-basicas-no-configurables" aria-label="Permalink to &quot;4. Teclas fijas básicas (No configurables)&quot;">​</a></h2><p>Para garantizar un comportamiento coherente y determinista, las siguientes teclas actúan igual en todas las configuraciones:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Tecla</th><th style="text-align:left;">Contexto</th><th style="text-align:left;">Comportamiento estándar</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">Lista de resultados</td><td style="text-align:left;">Abre el elemento seleccionado (archivo, carpeta, app o acción).</td></tr><tr><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">Lista de resultados</td><td style="text-align:left;">Muestra y selecciona el elemento en el Explorador de archivos de Windows.</td></tr><tr><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">Lista de resultados</td><td style="text-align:left;">Ejecuta la aplicación seleccionada con privilegios de administrador.</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">Cualquier contexto</td><td style="text-align:left;">Borra el texto de búsqueda si lo hay; cierra la ventana o sale del menú si ya está vacía.</td></tr><tr><td style="text-align:left;"><code>Backspace</code></td><td style="text-align:left;">Menú de acciones</td><td style="text-align:left;">Sale del menú de acciones hacia la lista de resultados cuando el filtro está vacío.</td></tr><tr><td style="text-align:left;"><code>←</code> / <code>→</code> Flechas</td><td style="text-align:left;">Menú de acciones</td><td style="text-align:left;">Flecha izquierda vuelve al menú superior; flecha derecha entra en submenús.</td></tr><tr><td style="text-align:left;"><code>Alt+Space</code></td><td style="text-align:left;">Todas las ventanas</td><td style="text-align:left;">Bloqueado para evitar activar el menú del sistema en ventanas sin marco.</td></tr><tr><td style="text-align:left;"><code>Alt+F4</code></td><td style="text-align:left;">Ventanas Principal / Config</td><td style="text-align:left;">Cierra la ventana normalmente; bloqueado en ventanas Rápida, Incrustada y Vista previa.</td></tr></tbody></table><h2 id="_5-atajos-de-acciones-de-plugins-y-lista-negra" tabindex="-1">5. Atajos de acciones de plugins y lista negra <a class="header-anchor" href="#_5-atajos-de-acciones-de-plugins-y-lista-negra" aria-label="Permalink to &quot;5. Atajos de acciones de plugins y lista negra&quot;">​</a></h2><h3 id="atajos-de-acciones-de-plugins" tabindex="-1">Atajos de acciones de plugins <a class="header-anchor" href="#atajos-de-acciones-de-plugins" aria-label="Permalink to &quot;Atajos de acciones de plugins&quot;">​</a></h3><p>Los plugins pueden registrar atajos propios (p. ej. <code>Ctrl+Shift+C</code> para copiar rutas, o gestión de archivos: Cortar <code>Ctrl+X</code>, Copiar <code>Ctrl+C</code>, Pegar <code>Ctrl+V</code>, Eliminar <code>Delete</code>, Eliminación permanente <code>Shift+Delete</code>). Puedes consultarlos y reasignarlos en <strong>Configuración → Atajos de teclado → Acciones de plugins</strong>.</p><h3 id="lista-negra-de-procesos-y-omision-en-pantalla-completa" tabindex="-1">Lista negra de procesos y omisión en pantalla completa <a class="header-anchor" href="#lista-negra-de-procesos-y-omision-en-pantalla-completa" aria-label="Permalink to &quot;Lista negra de procesos y omisión en pantalla completa&quot;">​</a></h3><ul><li><strong>Omisión automática en pantalla completa</strong>: Cuando una aplicación se ejecuta en pantalla completa exclusiva (como juegos 3D o reproductores de vídeo), Lertaro omite automáticamente todos los atajos globales para no interferir.</li><li><strong>Lista negra de procesos personalizada</strong>: Añade ejecutables en <a href="./settings/hotkeys-page.html#lista-negra-de-procesos"><strong>Configuración → Atajos de teclado</strong></a> (p. ej. <code>game.exe</code>) para silenciar los atajos mientras ese proceso esté en primer plano.</li></ul>',26)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
